'use strict';
const $=id=>document.getElementById(id);
const labels={to_review:'To review',planned:'Planned',in_progress:'In progress',done:'Done',archived:'Archived',idea:'Idea',question:'Question',bug:'Issue',decision:'Decision',bank_statement:'Bank statement',investment:'Investment export',grocery:'Grocery receipt',other:'Other document',uploading:'Uploading',awaiting_review:'Awaiting review',failed:'Upload incomplete',imported:'Imported',rejected:'Not imported'};
let db,user,household,notes=[],filter='open',editing=null,signup=false,loading=false,uploads=[];
function message(id,text,error=false){$(id).textContent=text;$(id).className='message '+(error?'error':'success');}
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function dateText(value){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Lisbon'}).format(new Date(value));}
function author(id){return !id?'Added during setup':id===user.id?'You':'Household member';}
function fail(e){return e?.message||'Something went wrong. Please try again.';}
function showPage(page){for(const p of ['analysis','evolution','budget','income','dashboard','transactions','reports','investments','sources','notebook','uploads','guide'])$(p+'-page').hidden=p!==page;const financial=['analysis','evolution','budget','income','dashboard','transactions','reports','investments','sources'].includes(page);$('finance-controls').hidden=!financial;$('bank-selection').hidden=!financial;$('account-scope').hidden=!financial;$('finance-month').parentElement.hidden=['reports','sources'].includes(page);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('selected',b.dataset.page===page));if(page==='uploads')loadUploads();}
async function applySession(session){
 if(!session?.user){user=null;household=null;notes=[];uploads=[];window.FinanceView?.reset();$('app-view').hidden=true;$('auth-view').hidden=false;return;}
 user=session.user;
 try{
  const membership=await db.from('finance_members').select('household_id,role').eq('user_id',user.id).limit(1).maybeSingle();if(membership.error)throw membership.error;
  if(!membership.data){$('app-view').hidden=true;$('auth-view').hidden=false;message('auth-message','Esta conta ainda não tem acesso ao espaço da família. Usa o email convidado, confirma-o e volta a entrar.',true);return;}
  household=membership.data.household_id;
  const h=await db.from('finance_households').select('name').eq('id',household).single();if(h.error)throw h.error;
  $('household-name').textContent=h.data.name;$('signed-in-name').textContent=user.email;$('auth-view').hidden=true;$('app-view').hidden=false;message('auth-message','');await loadNotes();await window.FinanceView?.start(db,user,household,showPage);
 }catch(e){message('auth-message',fail(e),true);}
}
async function loadNotes(){
 if(loading||!household)return;loading=true;$('refresh').disabled=true;message('app-message','');
 try{const r=await db.from('finance_notes').select('*').eq('household_id',household).order('updated_at',{ascending:false}).limit(1001);if(r.error)throw r.error;notes=r.data.slice(0,1000);if(r.data.length>1000)message('app-message','Showing the latest 1,000 notes. Archive older resolved notes to keep your review manageable.');renderNotes();$('last-refreshed').textContent='Updated '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Lisbon'});}
 catch(e){message('app-message','Could not refresh your notes. '+fail(e),true);}finally{loading=false;$('refresh').disabled=false;}
}
function renderNotes(){
 const open=n=>!['done','archived'].includes(n.status);$('count-open').textContent=notes.filter(open).length;$('count-review').textContent=notes.filter(n=>n.status==='to_review').length;$('count-decisions').textContent=notes.filter(n=>n.kind==='decision'&&n.status!=='archived').length;
 const q=$('search').value.trim().toLowerCase();const list=notes.filter(n=>(filter==='all'?n.status!=='archived':filter==='open'?open(n):filter==='decisions'?n.kind==='decision'&&n.status!=='archived':n.status===filter)&&(!q||(n.title+' '+n.body+' '+n.resolution).toLowerCase().includes(q)));
 $('notes').replaceChildren();$('empty').hidden=list.length>0;
 for(const n of list){const card=node('article',undefined,'note-card');const top=node('div',undefined,'note-card-top');top.append(node('span',labels[n.kind],'kind'),node('span',labels[n.status],'status '+n.status));card.append(top,node('h3',n.title));if(n.body)card.append(node('p',n.body,'note-body'));if(n.resolution)card.append(node('p',n.resolution,'note-outcome'));const bottom=node('div',undefined,'note-bottom');const meta=node('span',author(n.updated_by)+' · '+dateText(n.updated_at));meta.title='Created: '+author(n.created_by)+' · '+dateText(n.created_at);const edit=node('button','Open note ↗','text-button');edit.type='button';edit.addEventListener('click',()=>openNote(n));bottom.append(meta,edit);card.append(bottom);$('notes').append(card);}
 document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));
}
function openNote(n=null){editing=n?{...n}:null;$('dialog-title').textContent=n?'A note to revisit':'A thought for next time';$('note-title').value=n?.title||'';$('note-kind').value=n?.kind||'idea';$('note-status').value=n?.status||'to_review';$('note-body').value=n?.body||'';$('note-resolution').value=n?.resolution||'';message('save-message','');$('note-dialog').showModal();$('note-title').focus();}
async function saveNote(event){event.preventDefault();if($('save-note').disabled)return;$('save-note').disabled=true;message('save-message','');try{
 const patch={title:$('note-title').value.trim(),kind:$('note-kind').value,status:$('note-status').value,body:$('note-body').value.trim(),resolution:$('note-resolution').value.trim()};if(!patch.title)throw Error('Please add a title.');
 let r;if(editing){r=await db.from('finance_notes').update(patch).eq('id',editing.id).eq('household_id',household).eq('version',editing.version).select('id');if(!r.error&&!r.data.length)throw Error('This note changed since you opened it. Copy your text, close this window, refresh the notebook and reopen the latest version. Your text has not been replaced.');}
 else r=await db.from('finance_notes').insert({...patch,household_id:household}).select('id');if(r.error)throw r.error;$('note-dialog').close();await loadNotes();message('app-message','Note saved for your next review.');
 }catch(e){message('save-message',fail(e),true);}finally{$('save-note').disabled=false;}}
async function loadUploads(){if(!household)return;try{const r=await db.from('finance_uploads').select('*').eq('household_id',household).order('created_at',{ascending:false}).limit(101);if(r.error)throw r.error;uploads=r.data.slice(0,100);$('uploads-list').replaceChildren();if(!uploads.length)$('uploads-list').append(node('p','No documents yet. Either of you can add the first one.','empty'));for(const f of uploads){const row=node('article',undefined,'upload-row');const info=node('div');info.append(node('strong',f.original_name),node('p',labels[f.source_kind]+' · '+(f.file_size/1024).toFixed(0)+' KB · '+dateText(f.created_at)+' · '+author(f.submitted_by)));if(f.context)info.append(node('p',f.context));const right=node('div',undefined,'right');right.append(node('span',labels[f.status],'status'));if(['awaiting_review','imported','rejected'].includes(f.status)){const b=node('button','Download','text-button');b.type='button';b.onclick=()=>download(f,b);right.append(b);}row.append(info,right);$('uploads-list').append(row);}if(r.data.length>100)$('uploads-list').append(node('p','Showing the latest 100 documents.','small muted'));}
 catch(e){message('upload-message','Could not load documents. '+fail(e),true);}}
async function download(f,b){b.disabled=true;try{const r=await db.storage.from('finance-uploads').createSignedUrl(f.storage_path,60,{download:f.original_name});if(r.error)throw r.error;const a=node('a','Open your file ↗','text-link');a.href=r.data.signedUrl;a.target='_blank';a.rel='noopener';b.replaceWith(a);}catch(e){message('upload-message',fail(e),true);b.disabled=false;}}
async function uploadFile(event){event.preventDefault();if($('upload-submit').disabled)return;const file=$('upload-file').files[0];if(!file)return;let record=null;$('upload-submit').disabled=true;message('upload-message','Saving your document…');try{
 const ext=file.name.split('.').pop().toLowerCase();if(!['csv','xlsx','xls','pdf','png','jpg','jpeg'].includes(ext))throw Error('Choose a CSV, Excel, PDF, PNG or JPG file.');if(!file.size||file.size>20971520)throw Error('Choose a non-empty file up to 20 MB.');
 const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join('');
 const existing=await db.from('finance_uploads').select('*').eq('household_id',household).eq('file_sha256',sha).maybeSingle();if(existing.error)throw existing.error;
 if(existing.data){if(existing.data.status!=='failed'||existing.data.submitted_by!==user.id)throw Error('This exact file is already in your household document list. Refresh the list to see its status.');record=existing.data;const retry=await db.from('finance_uploads').update({status:'uploading'}).eq('id',record.id).eq('status','failed').select('id');if(retry.error)throw retry.error;if(!retry.data.length)throw Error('This upload changed. Refresh and try again.');await db.storage.from('finance-uploads').remove([record.storage_path]);}
 else{const id=crypto.randomUUID();record={id,household_id:household,original_name:file.name.slice(0,250),storage_path:household+'/'+id+'/document.'+ext,file_sha256:sha,file_size:file.size,content_type:file.type||'application/octet-stream',source_kind:$('upload-kind').value,context:$('upload-context').value.trim(),status:'uploading'};const r=await db.from('finance_uploads').insert(record);if(r.error){record=null;throw r.error;}}
 const saved=await db.storage.from('finance-uploads').upload(record.storage_path,file,{contentType:record.content_type,upsert:false});if(saved.error)throw saved.error;
 const complete=await db.from('finance_uploads').update({status:'awaiting_review'}).eq('id',record.id).eq('status','uploading').select('id');if(complete.error)throw complete.error;if(!complete.data.length)throw Error('The file was saved but its status could not be confirmed. Refresh before trying again.');$('upload-form').reset();message('upload-message','Document saved privately and added to the shared review queue. Your totals have not changed.');await loadUploads();
 }catch(e){if(record){try{await db.from('finance_uploads').update({status:'failed'}).eq('id',record.id).eq('status','uploading');}catch{}}message('upload-message',fail(e)+' If an upload is incomplete, select the same file again to retry.',true);await loadUploads();}finally{$('upload-submit').disabled=false;}}
async function init(){
 if(!window.supabase||!window.FINANCE_CONFIG){message('auth-message','The sign-in service could not load. Please refresh this page.',true);return;}
 db=window.supabase.createClient(FINANCE_CONFIG.supabaseUrl,FINANCE_CONFIG.supabaseKey);
 const archive=$('drive-archive-link');if(archive&&FINANCE_CONFIG.driveArchiveUrl){try{const u=new URL(FINANCE_CONFIG.driveArchiveUrl);if(u.protocol==='https:'&&u.hostname==='drive.google.com'){archive.href=u.href;archive.hidden=false;}}catch{}}
 $('auth-toggle').onclick=()=>{signup=!signup;$('auth-title').textContent=signup?'Cria a tua conta Nesti':'Entra na tua Nesti';$('auth-help').textContent=signup?'Usa o email convidado para o espaço da tua família.':'Usa a tua conta pessoal para aceder às finanças da família.';$('auth-submit').textContent=signup?'Criar conta':'Entrar';$('auth-toggle').textContent=signup?'Já tens conta? Entra aqui':'Primeira visita? Cria a tua conta';$('password').autocomplete=signup?'new-password':'current-password';message('auth-message','');};
 $('auth-form').onsubmit=async e=>{e.preventDefault();$('auth-submit').disabled=true;message('auth-message','');try{const credentials={email:$('email').value.trim(),password:$('password').value};const r=signup?await db.auth.signUp({...credentials,options:{emailRedirectTo:location.origin}}):await db.auth.signInWithPassword(credentials);if(r.error)throw r.error;$('password').value='';if(signup&&!r.data.session)message('auth-message','Confirma a tua conta pelo email que enviámos. Depois, volta à Nesti para entrar.');else await applySession(r.data.session);}catch(e){message('auth-message',fail(e),true);}finally{$('auth-submit').disabled=false;}};
 $('sign-out').onclick=async()=>{const r=await db.auth.signOut();if(r.error)message('app-message',fail(r.error),true);else await applySession(null);};
 $('new-note').onclick=()=>openNote();$('close-dialog').onclick=$('cancel-note').onclick=()=>$('note-dialog').close();$('note-form').onsubmit=saveNote;$('search').oninput=renderNotes;$('refresh').onclick=loadNotes;$('refresh-uploads').onclick=loadUploads;$('upload-form').onsubmit=uploadFile;
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderNotes();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
 $('copy-brief').onclick=async()=>{const open=notes.filter(n=>!['done','archived'].includes(n.status));const text='Nesti: rever antes da próxima atualização\n\n'+open.map(n=>n.title+' ['+labels[n.status]+']\n'+n.body+(n.resolution?'\nOutcome / next step: '+n.resolution:'')+'\nNote ID: '+n.id+'; version: '+n.version).join('\n\n');try{await navigator.clipboard.writeText(text);message('app-message','Open notes copied. Paste them into your next update request.');}catch{message('app-message','Your browser did not allow copying. You can open and copy the individual notes.',true);}};
 db.auth.onAuthStateChange((event,session)=>{if(['SIGNED_IN','SIGNED_OUT','USER_UPDATED'].includes(event))setTimeout(()=>applySession(session),0);});
 const r=await db.auth.getSession();if(r.error)message('auth-message',fail(r.error),true);else await applySession(r.data.session);
}
init();
